/*
 * A267355  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 124" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A267355
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(n) generated by iterating Rule 124 cellular automaton,
 *            starting from a single ON cell. The sequence is read row‑by‑row
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>

/* Integer floor square root for uint64_t */
static idx_t floor_isqrt(idx_t n)
{
    idx_t low = 0, high = n, mid;
    while (low <= high)
    {
        mid = low + ((high - low) >> 1);
        unsigned __int128 sq = (unsigned __int128)mid * mid;
        if (sq <= n)
        {
            low = mid + 1;
        }
        else
        {
            if (mid == 0) break;
            high = mid - 1;
        }
    }
    return high;
}

/* Rule 124 lookup table (bits 12345678 correspond to neighborhoods
   111,110,101,100,011,010,001,000 */ 
static const unsigned char rule124[8] = {0,0,1,1,1,1,1,0};

seq_t a(idx_t n)
{
    /* Find the row containing index n.  Each row r has length 2r+1,
       and cumulative terms up to row r equal (r+1)^2.   */
    idx_t r = floor_isqrt(n);
    idx_t j = n - r * r;      /* position within the row */
    if (r == 0) return (seq_t)1; /* first row is a single ON cell */

    /* Allocate buffers large enough for the final row. */
    idx_t max_len = 2 * r + 1;
    seq_t *prev = (seq_t *)calloc(max_len, sizeof(seq_t));
    seq_t *curr = (seq_t *)calloc(max_len, sizeof(seq_t));

    prev[0] = 1;            /* row 0 */
    idx_t prev_len = 1;      /* number of cells in previous row */

    for (idx_t k = 1; k <= r; ++k)
    {
        idx_t len = 2 * k + 1;      /* length of current row */

        for (idx_t p = 0; p < len; ++p)
        {
            unsigned char left   = (p >= 2)     ? (unsigned char)prev[p - 2] : 0;
            unsigned char center = (p >= 1 && p - 1 < prev_len)
                                  ? (unsigned char)prev[p - 1] : 0;
            unsigned char right  = (p < prev_len) ? (unsigned char)prev[p] : 0;

            unsigned char pat = (left << 2) | (center << 1) | right;
            curr[p] = (seq_t)rule124[pat];
        }

        /* Prepare for next iteration */
        for (idx_t t = 0; t < len; ++t) prev[t] = curr[t];
        prev_len = len;
    }

    seq_t result = prev[j];
    free(prev);
    free(curr);
    return result;
}
